def jsonb_get(data, path: str, default=None):
    """安全读取嵌套 JSON 字段。
    路径用点分隔（如 'a.b.c'）；任一层缺失或不是 dict 都返回 default。
    """
    keys = path.split('.')
    for key in keys:
        if isinstance(data, dict) and key in data:
            data = data[key]
        else:
            return default
    return data

